import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const TYPE_ALL = '감가상각비 현황(전체)';
const TYPE_MONTHLY = '감가상각비 현황(월별)';
const TYPE_CHANGE = '고정자산 명세서 및 변동 현황';
const TYPE_LEDGER = '고정자산 관리대장';
const TYPE_UNDEPRECIATED = '미상각자산 감가상각 명세서';
const REPORT_TYPES = [TYPE_ALL, TYPE_MONTHLY, TYPE_CHANGE, TYPE_LEDGER, TYPE_UNDEPRECIATED];

// 조회 기준 연도가 없으면 현재 연도를 쓴다 (가정)
const YEAR_EXPR = 'COALESCE(CAST(:year AS integer), CAST(date_part(\'year\', now()) AS integer))';

// 감가상각비 집계: 정액법(취득원가 / (내용연수 x 12))을 월 단위로 합산한다 (가정: 집계 방식 미정, 개발 담당자 결정)
// 월을 주면 그 달만, 안 주면 기준 연도 12개월 전체를 합한다.
const DEPRECIATION_SQL =
  'COALESCE((SELECT ROUND(SUM(fa.acquisition_cost / (fa.useful_life_years * 12)), 2)' +
  ' FROM generate_series(COALESCE(CAST(:month AS integer), 1), COALESCE(CAST(:month AS integer), 12)) AS m(n)' +
  ' WHERE fa.is_depreciable = true' +
  ' AND fa.useful_life_years IS NOT NULL' +
  ' AND fa.depreciation_start_date IS NOT NULL' +
  ' AND fa.depreciation_start_date < (make_date(' + YEAR_EXPR + ', m.n, 1) + interval \'1 month\')' +
  ' AND (fa.depreciation_start_date + make_interval(years => fa.useful_life_years)) > make_date(' + YEAR_EXPR + ', m.n, 1)' +
  '), 0) AS "depreciationAmount"';

@Controller('api/v1')
export class FnSfr01102Controller {
  @Get('/fixed-asset-reports')
  async listFixedAssetReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '예산·회계 담당자');
    const query = checks.queryOf(req.query);

    const reportType = text(query['reportType']);
    if (reportType === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 유형을 선택해 주세요.');
    }
    if (!REPORT_TYPES.includes(reportType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 유형이 올바르지 않습니다.');
    }

    const yearText = text(query['year']);
    if (yearText !== null && !/^\d{4}$/.test(yearText)) {
      throw new ApiError(422, 'INVALID_REPORT_CONDITION', '조회 기준 연도 형식이 올바르지 않습니다. (예: 2025)');
    }
    const monthText = text(query['month']);
    if (monthText !== null && (!/^\d{1,2}$/.test(monthText) || Number(monthText) < 1 || Number(monthText) > 12)) {
      throw new ApiError(422, 'INVALID_REPORT_CONDITION', '조회 월 형식이 올바르지 않습니다. (1~12)');
    }
    if (reportType === TYPE_MONTHLY && monthText === null) {
      throw new ApiError(422, 'INVALID_REPORT_CONDITION', '월별 현황은 조회 월을 입력해야 합니다.');
    }

    const accountItemText = text(query['accountItemId']);
    if (accountItemText !== null && !/^\d+$/.test(accountItemText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 형식이 올바르지 않습니다.');
    }
    const pageText = text(query['page']);
    if (pageText !== null && !/^\d+$/.test(pageText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 형식이 올바르지 않습니다.');
    }
    const sizeText = text(query['size']);
    if (sizeText !== null && (!/^\d+$/.test(sizeText) || Number(sizeText) < 1)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기 형식이 올바르지 않습니다.');
    }
    const page = pageText === null ? 0 : Number(pageText);
    const size = Math.min(sizeText === null ? DEFAULT_SIZE : Number(sizeText), MAX_SIZE);

    // 월은 월별 현황에서만 쓴다 (전체 현황은 기준 연도 12개월)
    const monthValue = reportType === TYPE_MONTHLY ? Number(monthText) : null;

    let fromWhere =
      ' FROM fixed_asset fa' +
      ' LEFT JOIN account_item ai ON ai.account_item_id = fa.account_item_id';
    let changeColumns =
      'CAST(NULL AS varchar) AS "changeType", CAST(NULL AS date) AS "changeDate"';
    let orderBy = ' ORDER BY fa.asset_code, fa.asset_no';
    if (reportType === TYPE_CHANGE) {
      fromWhere +=
        ' LEFT JOIN asset_change ac ON ac.fixed_asset_id = fa.fixed_asset_id' +
        ' AND date_part(\'year\', ac.change_date) = ' + YEAR_EXPR;
      changeColumns = 'ac.change_type AS "changeType", ac.change_date AS "changeDate"';
      orderBy = ' ORDER BY fa.asset_code, fa.asset_no, ac.change_date';
    }
    fromWhere +=
      ' WHERE (CAST(:assetCode AS varchar) IS NULL OR fa.asset_code = CAST(:assetCode AS varchar))' +
      ' AND (CAST(:accountItemId AS bigint) IS NULL OR fa.account_item_id = CAST(:accountItemId AS bigint))';
    if (reportType === TYPE_ALL || reportType === TYPE_MONTHLY) {
      fromWhere += ' AND fa.is_depreciable = true';
    }
    // 미상각자산 = 상각 대상이 아닌 자산으로 본다 (가정)
    if (reportType === TYPE_UNDEPRECIATED) {
      fromWhere += ' AND fa.is_depreciable = false';
    }

    const params = {
      year: yearText === null ? null : Number(yearText),
      month: monthValue,
      assetCode: text(query['assetCode']),
      accountItemId: accountItemText,
      limit: size,
      offset: page * size,
    };

    return transaction(async (db) => {
      const counts = await db.query('SELECT COUNT(*) AS "total"' + fromWhere, params);
      const rows = await db.query(
        'SELECT fa.asset_code AS "assetCode", fa.asset_name AS "assetName",' +
          ' fa.acquisition_date AS "acquisitionDate", fa.acquisition_cost AS "acquisitionCost",' +
          ' ai.account_name AS "accountName", ' + changeColumns + ', ' + DEPRECIATION_SQL +
          fromWhere + orderBy + ' LIMIT :limit OFFSET :offset',
        params,
      );
      return {
        items: rows,
        page,
        size,
        total: Number(counts[0]['total']),
      };
    });
  }
}

function text(value: unknown): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  const s = String(value).trim();
  return s === '' ? null : s;
}

