import { useState } from 'react';
import {
  Band,
  call,
  DataTable,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  Select,
  Tiles,
  TextInput,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const REPORT_TYPES: [string, string][] = [
  ['감가상각비 현황(전체)', '감가상각비 현황(전체)'],
  ['감가상각비 현황(월별)', '감가상각비 현황(월별)'],
  ['고정자산 명세서 및 변동 현황', '고정자산 명세서 및 변동 현황'],
  ['고정자산 관리대장', '고정자산 관리대장'],
  ['미상각자산 감가상각 명세서', '미상각자산 감가상각 명세서'],
];

const MONTHS: [string, string][] = Array.from({ length: 12 }, (_, i): [string, string] => [String(i + 1), (i + 1) + '월']);

const SIZE = 20;

export default function FnSfr01102Page({ role, notify }: PageProps) {
  const [reportType, setReportType] = useState('');
  const [year, setYear] = useState<number | string>('');
  const [month, setMonth] = useState('');
  const [assetCode, setAssetCode] = useState('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(
    async () => {
      if (applied === null) {
        return { items: [], page: 0, size: SIZE, total: 0 };
      }
      return call<Page>('GET', '/fixed-asset-reports', role, undefined, { ...applied, page, size: SIZE });
    },
    [applied, page, role],
  );

  const rows = data?.items ?? [];
  const pageSum = rows.reduce((sum, r) => sum + Number(r['depreciationAmount'] ?? 0), 0);

  function search() {
    if (reportType === '') {
      setFormError('조회 유형을 선택해 주세요.');
      return;
    }
    if (year !== '' && !/^\d{4}$/.test(String(year))) {
      setFormError('조회 기준 연도는 4자리 숫자로 입력해 주세요.');
      return;
    }
    if (reportType === '감가상각비 현황(월별)' && month === '') {
      setFormError('월별 현황은 조회 월을 선택해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ reportType, year, month, assetCode, accountItemId });
  }

  function reset() {
    setReportType('');
    setYear('');
    setMonth('');
    setAssetCode('');
    setAccountItemId('');
    setFormError('');
    setPage(0);
    setApplied(null);
  }

  const columns: Column[] = [
    { key: 'assetCode', label: '자산코드' },
    { key: 'assetName', label: '자산명' },
    { key: 'acquisitionDate', label: '취득일', render: (r) => <DateText value={r['acquisitionDate']} /> },
    { key: 'acquisitionCost', label: '취득원가', render: (r) => <Num value={r['acquisitionCost']} /> },
    { key: 'accountName', label: '계정과목 명칭' },
    { key: 'changeType', label: '변동 구분' },
    { key: 'changeDate', label: '변동 일자', render: (r) => <DateText value={r['changeDate']} /> },
    { key: 'depreciationAmount', label: '감가상각비 집계 금액', render: (r) => <Num value={r['depreciationAmount']} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data?.total ?? 0} />],
            ['이 쪽 감가상각비 합계', <Num value={pageSum} />],
          ]}
        />
      </section>

      <section className="box span-12">
        <h2>감가상각 현황·관리대장</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 유형" required>
            <Select value={reportType} onChange={setReportType} options={REPORT_TYPES} />
          </Field>
          <Field label="조회 기준 연도">
            <NumberInput value={year} onChange={setYear} />
          </Field>
          <Field label="월별 조회 대상 월" required={reportType === '감가상각비 현황(월별)'}>
            <Select value={month} onChange={setMonth} options={MONTHS} placeholder="전체" />
          </Field>
          <Field label="자산코드">
            <TextInput value={assetCode} onChange={setAssetCode} />
          </Field>
          <Field label="계정과목">
            <LookupSelect table="account_item" role={role} value={accountItemId} onChange={setAccountItemId} placeholder="전체" />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={data?.total ?? 0} />
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty={applied === null ? '조회 유형을 선택하고 조회해 주세요.' : loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={data?.page ?? 0} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {detail !== null && (
        <Drawer title="고정자산 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['자산코드', String(detail['assetCode'] ?? '')],
              ['자산명', String(detail['assetName'] ?? '')],
              ['취득일', <DateText value={detail['acquisitionDate']} />],
              ['취득원가', <Num value={detail['acquisitionCost']} />],
              ['계정과목 명칭', String(detail['accountName'] ?? '')],
              ['변동 구분', String(detail['changeType'] ?? '')],
              ['변동 일자', <DateText value={detail['changeDate']} />],
              ['감가상각비 집계 금액', <Num value={detail['depreciationAmount']} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
